INSERT INTO `hotels` (city, slug, status, seo_title, meta_description, meta_keywords, og_image, banner_image, name, address, airport_time, station_time, description, room_inventory, indoor_venues, outdoor_venues, guest_capacity, reception_capacity, highlights, faqs, external_hotel_id, total_rooms)
SELECT 'indore', 'the-park-indore', 'published', 'The Park Indore Weddings Packages, Reviews, Cost & Booking', 'The Park Indore offers contemporary wedding venues & bespoke event packages. Discover wedding cost, pricing & direct booking options for your big day.', 'the park indore wedding, the park indore wedding cost, the park indore wedding price, the park indore wedding package, the park hotel indore wedding, the park hotel indore wedding cost', '/storage/hotel/seo/mmS3OIjdvvAvMY6PgvfvFv4IaN83J9o7AseX6CVf.jpg', '/storage/hotels/banners/mH89cti2iV9XbwnFYBvu0o3vIz4HMc1WGxeJn5I0.jpg', 'The Park Indore', 'MR 10 Rd, Scheme 134, Nipania, Indore, Madhya Pradesh 452016, India', '25 Minutes', '20 Minutes', '<p>Sharp glass architecture, mood-lit interiors and rose-gold detailing give&nbsp;<strong>The Park Indore</strong> an atmosphere that feels more like a contemporary lifestyle destination than a conventional wedding hotel. Recently opened in Indore’s upscale Nipania neighbourhood, this 5-star luxury property blends bold design with a lively social energy that instantly draws people in. The hotel feels polished yet playful, with rooftop views, statement art pieces and stylish lounges creating a setting that naturally suits a modern&nbsp;<strong>wedding in Madhya Pradesh</strong>. Its location also keeps the airport and key city hubs within comfortable reach for travelling guests.</p><p><strong>The Park Indore</strong>, which spans 43,800 square feet, allows you to organise weddings in your own style, from elaborate festivities to more private get-togethers. Sangeet nights and receptions get scale and effect from the Malhar Grand Ballroom''s open, pillarless design. The atmosphere drastically changes outside with the garden and beautifully manicured lawns. Moreover, Garden By The Park provides a serene, open environment that is ideal for casual cocktail evenings and photography.</p><p>A wedding at&nbsp;<strong>The Park Indore</strong> doesn’t stay limited to the venue alone. Guests often find themselves unwinding by Aqua’s rooftop pool or stepping out to explore nearby landmarks like Rajwada Palace, Sarafa Bazaar and Chappan Dukan. It all comes together in a way that feels naturally woven into the rhythm of Indore, making the celebration feel lively, grounded and very much part of the city.</p>', '99 rooms with suites', 'Malhar Grand Ballroom, Triveni Hall, Revati Hall', 'The Lawn, The Tamarind Tree, Garden By The Park', '250', '250', '[{"image": "/storage/hotels/amenities/51Jw4FwONbEkdviyl5898vPrjp6bF2oNST3Bao1N.jpg", "title": "3+ dining venues onsite"}, {"image": "/storage/hotels/amenities/zUZkyg9ZcqmLZoIbH9Whbcz6UNlU4ewJOW7ZVxsE.jpg", "title": "Skyline poolside lounge evenings"}]', '[{"id": 1193, "question": "Are there nearby attractions or activities for international guests around The Park Indore?", "answer": "<p>Guests staying at&nbsp;<strong>The Park Indore</strong> can explore Rajwada Palace, Lal Bagh Palace, Sarafa Bazaar, Chappan Dukan, Kanch Mandir and Ralamandal Wildlife Sanctuary between wedding celebrations. The hotel’s central location also makes café hopping and local shopping outings convenient for international guests.</p>"}, {"id": 1194, "question": "Is an early check-in available at The Park Indore?", "answer": "<p>Yes, an early check-in facility can be arranged at&nbsp;<strong>The Park Indore</strong>. The standard check-in time at the property is 2:00 pm, and the check-out time is 12:00 noon.</p>"}, {"id": 1195, "question": "What are the timing restrictions for events and music at The Park Indore?", "answer": "<p>Timing and music restrictions at&nbsp;<strong>The Park Indore</strong> are managed as per local regulations and hotel policies. For exact cut-off timings and permissions, it’s best to check with the hotel or the Viraaya Weddings team beforehand.</p>"}, {"id": 1196, "question": "⁠How early should I book The Park Indore?", "answer": "<p>For peak wedding months, it’s best to book&nbsp;<strong>The Park Indore</strong> around 12 to 18 months in advance. Dates during the winter and festive seasons usually get reserved quickly.</p>"}, {"id": 1197, "question": "Can I bring my own alcohol for a wedding at The Park Indore?", "answer": "<p>Outside alcohol is generally not permitted at&nbsp;<strong>The Park Indore</strong>, with beverages arranged through the hotel’s in-house bar as per policy. Please note that all drinks are billed separately from standard wedding packages, based on consumption.</p>"}]', '297', '99'
WHERE NOT EXISTS (SELECT 1 FROM `hotels` WHERE `city` = 'indore' AND `slug` = 'the-park-indore');
