INSERT INTO `hotels` (city, slug, status, seo_title, meta_description, meta_keywords, og_image, banner_image, name, address, airport_time, station_time, description, room_inventory, indoor_venues, outdoor_venues, guest_capacity, reception_capacity, highlights, faqs, external_hotel_id, total_rooms)
SELECT 'jodhpur', 'welcomheritage-bal-samand-lake-palace-jodhpur', 'published', 'WelcomHeritage Bal Samand Lake Palace Wedding Cost', 'WelcomHeritage Bal Samand Lake Palace offers regal wedding venues & clear wedding cost details. Plan your royal Jodhpur celebration perfectly. Book Now!', 'bal samand lake palace wedding, bal samand lake palace wedding cost, bal samand lake palace restaurant jodhpur, welcomheritage bal samand lake palace wedding', '/storage/hotel/seo/Wr5s6cJfeGQOadBjrHmQ6rvmxuuoiNPDPCtNsRUH.jpg', '/storage/hotels/banners/yc6vbzAfHNmE6pudMlz0v9NZYBHpqfmmduQ2aKtT.jpg', 'WelcomHeritage Bal Samand Lake Palace Jodhpur', 'BSF STC, Mandore Road, Mandore, Jodhpur, Rajasthan 342026, India, India', '30 minutes', '25 Minutes', '<p>A&nbsp;<strong>destination wedding at WelcomHeritage Bal Samand Lake Palace</strong> doesn’t feel like a typical venue booking in Jodhpur. It feels like hosting your wedding at a private royal estate. Spread across nearly 60 acres, the property sits beside Balsamand Lake, surrounded by orchards and open greens, far removed from the noise of the city. For a&nbsp;<strong>destination wedding in Jodhpur</strong>, this kind of space and quiet is hard to come by.</p><p>Built somewhere around the 17th century as a summer residence for Jodhpur’s royals, this palace-turned-heritage hotel carries a strong Rajputana identity. Featuring red sandstone architecture, carved details and airy terraces, the property’s construction is bound to leave your guests in awe. The 36 rooms are split between garden-facing accommodations and suites within the palace itself, giving guests the option of a more contemporary stay or a classic, heritage-led experience. It’s intimate in style but expansive in setting.</p><p><strong>Weddings at the Bal Samand Lake Palace</strong> unfold across vast lawns like the Gold Flaw Main Lawn and lake-facing spaces that can host large gatherings with ease. Add traditional hospitality, regional dining and the quiet presence of the lake, and a&nbsp;<strong>destination wedding at WelcomHeritage Bal Samand Lake Palace</strong> feels timeless and deeply atmospheric.</p>', '36', 'Garden Restaurant, Palace Bar Area', 'Gold Flaw Main Lawn, Front Lawn, Poolside Lawn, Palace Lawn, North Lawn, Lake Terrace', '100', '120', '[{"image": "/user/assets/images/hotal02.png", "title": "4+ restaurants and bars onsite"}, {"image": "/user/assets/images/hotal03.png", "title": "Curated themed dining for celebrations"}]', '[{"id": 732, "question": "Which is the nearest airport to the WelcomHeritage Bal Samand Lake Palace?", "answer": "<p>Jodhpur Airport (JDH) is the nearest airport to&nbsp;<strong>WelcomHeritage Bal Samand Lake Palace,</strong> about 11–12 km away, with a 20-40 minute drive.</p>"}, {"id": 733, "question": "Is an early check-in available for wedding guests at WelcomHeritage Bal Samand Lake Palace?", "answer": "<p>Yes, an early check-in facility is available at this heritage hotel, which is subject to hotel availability. The standard time to check-in at&nbsp;<strong>WelcomHeritage Bal Samand Lake Palace</strong> is 2:00 pm, and guests can check out by 11:00 am.</p>"}, {"id": 734, "question": "What is the ideal budget for a 2-night wedding at WelcomHeritage Bal Samand Lake Palace?", "answer": "<p>A&nbsp;<strong>destination wedding at WelcomHeritage Bal Samand Lake Palace&nbsp;</strong>for a 2-night celebration typically ranges between INR 50 lakhs and INR 85 lakhs. For a more accurate estimate, you can use Viraaya Weddings'' Cost Calculator based on your requirements.</p>"}, {"id": 735, "question": "⁠Can we bring our own wedding planner to WelcomHeritage Bal Samand Lake Palace?", "answer": "<p>Yes, you can bring your own wedding planner or decorator to&nbsp;<strong>WelcomHeritage Bal Samand Lake Palace</strong>. The hotel team coordinates with external vendors, though approvals and basic guidelines may apply.</p>"}, {"id": 736, "question": "Can I bring my own alcohol to WelcomHeritage Bal Samand Lake Palace?", "answer": "<p>No, you cannot bring your own alcohol to&nbsp;<strong>WelcomHeritage Bal Samand Lake Palace</strong>. The hotel serves all beverages through its in-house bar and charges based on consumption.</p>"}]', '346', '36'
WHERE NOT EXISTS (SELECT 1 FROM `hotels` WHERE `city` = 'jodhpur' AND `slug` = 'welcomheritage-bal-samand-lake-palace-jodhpur');
