INSERT INTO `hotels` (city, slug, status, seo_title, meta_description, meta_keywords, og_image, banner_image, name, address, airport_time, station_time, description, room_inventory, indoor_venues, outdoor_venues, guest_capacity, reception_capacity, highlights, faqs, external_hotel_id, total_rooms)
SELECT 'udaipur', 'wyndham-grand-udaipur-fatehsagar-lake', 'published', 'Wyndham Grand Udaipur Fatehsagar Lake Wedding Cost', 'Explore wedding costs & packages at Wyndham Grand Udaipur Fatehsagar Lake with Viraaya Weddings. Check & Plan a royal dream destination wedding in Udaipur...', 'wyndham grand udaipur wedding, wyndham grand udaipur wedding cost, wyndham udaipur wedding, wyndham grand udaipur resort & spa', '/storage/hotel/seo/YfF8lfJc7OioR0OgfgDpgRSzRZ0uXTYcqMgxoFxI.png', '/storage/hotels/banners/4A8CdCRayhpvobwMa0JtSaqFvvsdy432yzbllKpY.jpg', 'Wyndham Grand Udaipur Fatehsagar Lake', 'Near, Rani Rd, off Fateh Sagarlake, Shilpgram, Hawala Khurd, Udaipur, Rajasthan 313011, India', '40 Minutes', '20 Minutes', '<p>Spread across 26 hectares and set close to the serene waters of Fateh Sagar Lake, <strong>Wyndham Grand Udaipur Resort &amp; Spa</strong> feels like a quiet world of its own. Surrounded by the green Aravalli hills, its palace-inspired design draws from Rajputana architecture, with broad walkways and carved details. The open layout allows guests to move around with ease and settle in comfortably during wedding celebrations.</p><p>Ballrooms at the venue have a sophisticated charm, while lawns open out to the sky and temple-inspired gardens bring a sense of calm to the setting. As the sun sets around the lake, mandap moments here feel personal and rooted in heritage.</p><p>With attentive service and thoughtfully curated dining, the resort makes it easy to host guests with different preferences. It suits families travelling from across the world, offering plenty of space and a calm atmosphere that you and your guests will remember fondly.</p>', '140 rooms with 13 suites', 'Grand Ballroom, Banquet Hall', 'Rooftop Terrace, Open Lawns, Amphitheatre', '350', '350', '[{"image": "/storage/hotels/amenities/ZOcnSaQBMdmNgHlT99fiNc2iAGhXKFAmXMBGU2Au.jpg", "title": "1.\t5+ restaurants and bars onsite"}, {"image": "/storage/hotels/amenities/UQWRDZW9tMbkfM5VD0e43zRUQXvNxSJVCIoeAycK.jpg", "title": "2.\tSunset boat rides and intimate dinners"}, {"image": "/storage/hotels/amenities/ojpBCRIsmkUSMh83W3UEXB0PXJhaiuLQYYa3uRD0.jpg", "title": "3.\tCurated Udaipur tours and cultural experiences"}]', '[{"id": 74, "question": "How much does a wedding at Wyndham Grand Udaipur Resort & Spa cost?", "answer": "<p>The standard <strong>cost of a destination wedding at Wyndham Grand Udaipur Resort</strong> for a 3-day 2-night celebration ranges between INR 30 lakhs and INR 60 lakhs. Use our Cost Calculator to get an exact quote: enter your room requirements, total guest capacity, preferred dates and other details to get instant results.</p>"}, {"id": 75, "question": "How early should I book the Wyndham Grand Udaipur Resort & Spa for a wedding?", "answer": "<p>Wyndham Grand Udaipur Resort &amp; Spa is a premium venue in one of India’s most popular destination wedding cities, so it is advisable to begin planning and secure your booking at least 12 to 18 months in advance. Dates between October and March fall within the peak season, so planning further ahead during this period can help ensure better availability.</p>"}, {"id": 76, "question": "Which is better: Wyndham Grand Udaipur Resort & Spa or Taj Aravali Resort & Spa, Udaipur?", "answer": "<p>Wyndham Grand Udaipur Resort &amp; Spa has around 140 rooms and is a good choice for a well-planned wedding with a scenic setting. It offers budgets typically between INR 30 and 60 lakhs and is located about 45 to 60 minutes from the airport.</p><p>Taj Aravali Resort &amp; Spa, Udaipur, has about 181 rooms and larger venues, making it better suited for bigger, more luxurious celebrations. It is around 50 minutes from the airport, with wedding budgets usually ranging from INR 2 crore to INR 9 crore.</p><p>Wyndham Grand works well for a more balanced, mid-range wedding, while Taj Aravali is ideal for larger, luxury-led celebrations.</p>"}, {"id": 77, "question": "What is the check-in time at Wyndham Grand Udaipur Resort & Spa, and can we check-in early?", "answer": "<p>The standard check-in time at Wyndham Grand Udaipur Resort &amp; Spa is 3:00 pm, and check-out time is 12:00 noon. Early check-in can be accommodated; however, availability is subject to hotel availability.</p>"}, {"id": 78, "question": "What is the liquor policy for a destination wedding at Wyndham Grand Udaipur Resort & Spa?", "answer": "<p>Alcohol is allowed at Wyndham Grand Udaipur Resort &amp; Spa, but all beverages served during events must be sourced through the hotel. Outside liquor is not permitted. Drinks are billed separately based on consumption and are generally not part of the standard wedding package.</p>"}]', '39', '140'
WHERE NOT EXISTS (SELECT 1 FROM `hotels` WHERE `city` = 'udaipur' AND `slug` = 'wyndham-grand-udaipur-fatehsagar-lake');
